-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := '515a9435-52c0-4c91-afd0-375e2150fb96';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Checking What the AI Wrote', 'The existing lessons show you how to get an AI to write code. This one is about the harder half — knowing whether the code it wrote is safe to ship.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'How to Vibe Code Without It Falling Apart', 'A fast, dense rundown of what separates vibe coding that works from vibe coding that produces an unmaintainable mess. Under 6 minutes.', 'https://www.youtube.com/watch?v=PLKrSVuT-Dg', 1,
      array['Work in small, reviewable steps instead of one giant prompt', 'Give the AI the context it needs to produce code that fits your project', 'Recognise the point where a codebase has outrun your understanding of it'],
      'Vibe coding gets you to something working astonishingly fast. The failure mode is not that it does not work — it is that it works, then stops working, and you have no idea why, because you never understood it.

What actually separates the people who ship from the people who get stuck:

SMALL STEPS. Ask for one feature, check it, commit it, then ask for the next. "Build me a whole marketplace" produces a thousand lines you will never read. One clear change at a time stays reviewable, and when something breaks you know exactly what caused it.

GIVE IT CONTEXT. The AI cannot see your project''s conventions unless you show it. Point it at the existing files, tell it what stack you are on, say "match the pattern in this file". Otherwise it invents a second way of doing something you already do, and now your project has two.

READ WHAT COMES BACK. Not line by line at first, but enough to answer: what does this do, roughly? What did it add that I did not ask for? Did it install a new dependency? That last one catches a lot.

KNOW WHEN TO STOP AND UNDERSTAND. The dangerous moment is when you stop being able to describe what your own app does. If you cannot explain roughly how a feature works, you cannot debug it, and you certainly cannot judge whether it is secure. That is the moment to slow down and read, not to prompt harder.

The honest framing: the AI is a very fast junior developer who never says "I''m not sure". Everything a junior''s work needs — review, testing, questions — this needs too.',
      'Take something you built with AI help, or build a small feature now. Then, without looking at the code, write two or three sentences explaining what it does and how. Now open the code and check whether your description was right. The gap between what you thought it did and what it does is precisely the risk you are carrying.',
      '[{"question":"What is the clearest sign you should stop prompting and start reading?","options":["You can no longer describe roughly how your own feature works","The AI takes longer than usual to respond","The file has more than 100 lines","You have used the tool for over an hour"],"correct_index":0},{"question":"Why ask for one feature at a time rather than the whole app?","options":["Small changes stay reviewable, and a break is traceable to one step","The AI charges per request","Large requests are always rejected","It makes the code run faster"],"correct_index":0}]'::jsonb),
    (v_m1, 'Reviewing AI Code Before It Goes Live', 'A practical walkthrough of taking AI-generated code from "it runs on my machine" to something safe to put in front of real users. About 19 minutes.', 'https://www.youtube.com/watch?v=Eco1O4g5TGg', 2,
      array['Review generated code for the mistakes AI makes most often', 'Test a feature deliberately rather than assuming it works', 'Keep secrets and API keys out of code that gets shared or published'],
      'The specific things to look for, because AI-generated code fails in patterns:

SECRETS IN THE CODE. This is the one that causes real damage. AI will happily write your API key directly into a file, and if you push that to a public repository, automated scanners find it within minutes — people have been billed thousands overnight for leaked cloud keys. Keys belong in environment variables, and the file holding them belongs in `.gitignore`. Check this every single time.

NO INPUT VALIDATION. Generated code usually assumes input is well-formed. Real users type nothing, paste emoji, enter a negative quantity, or deliberately probe your form. Anything a user can type must be checked before it is used, and especially before it reaches a database.

EVERYTHING IS PUBLIC BY DEFAULT. AI often writes the version where any visitor can read any record, because that is simpler and it works in testing. Ask explicitly: who is allowed to see this, and who is allowed to change it? Then check the code actually enforces that.

DEPENDENCIES YOU DID NOT ASK FOR. Watch for new packages appearing. Each one is code from a stranger running inside your project.

ERROR HANDLING THAT HIDES PROBLEMS. Generated code loves to swallow errors silently so nothing crashes. That turns a loud failure into a silent wrong answer, which is worse.

AND ACTUALLY TEST IT. Not the happy path — you already know that works. Submit the form empty. Enter a huge number. Click the button twice quickly. Log out and try to reach the page directly by URL. Five minutes of trying to break your own thing is worth more than an hour of reading it.',
      'Open something you have built with AI and hunt specifically for two things. First, search the whole project for anything that looks like a key or password sitting in a file — then confirm `.env` or equivalent is listed in `.gitignore`. Second, pick one form and attack it: submit it empty, paste 500 characters into a short field, enter a negative number. Write down what broke. Fix one of them.',
      '[{"question":"Why is an API key written directly into a code file so dangerous?","options":["Pushing it to a public repository exposes it to automated scanners within minutes","It makes the application run more slowly","The key stops working once saved to a file","It uses more disk space"],"correct_index":0},{"question":"What is the most useful way to test a feature you just generated?","options":["Deliberately try to break it — empty input, huge values, double clicks, direct URLs","Run the happy path once more to confirm it still works","Ask the AI whether the code is correct","Check that the file compiles"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Git, and Not Losing Your Work', 'Vibe coding means accepting large changes you did not write. Version control is what makes that safe — it is the undo button for everything the AI does.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'What Git Actually Does', 'A clear, concise explanation of how Git works underneath — commits, branches and the model everything else is built on. About 4 minutes.', 'https://www.youtube.com/watch?v=e9lnsKot_SQ', 1,
      array['Explain what a commit is and why it is a save point rather than a saved file', 'Describe what a branch is for', 'Understand why version control matters more when AI writes the code'],
      'Git is the single most valuable thing on this page for someone vibe coding, and most beginners skip it because it looks like a developer ritual.

Here is why it is not optional for you specifically. When an AI rewrites forty lines across six files in one go, and the app breaks, "undo" in your editor will not save you. Git will. It lets you go back to the exact state where things worked, look at precisely what changed, and throw away the bad attempt without losing the good work from an hour ago.

A COMMIT is a save point for the entire project at one moment, with a message saying what changed. Not a saved file — a snapshot of everything, that you can return to at any time.

A BRANCH is a parallel line of work. You leave your working version untouched, try something risky on a branch, and either merge it in or throw it away. For vibe coding this is the perfect fit: branch before a big AI-driven change, and if it goes badly, delete the branch and nothing is lost.

The habit that makes this work: COMMIT BEFORE EACH AI CHANGE, not after several. A commit costs you five seconds. Not having one costs you an evening.

Write messages that describe intent, not mechanics — "add password reset" rather than "changes". Six weeks later, that message is the only thing telling you what the snapshot was for.',
      'In a project you are working on, make a commit right now with a clear message. Then ask an AI to make a change you are not confident about. Look at the difference between your commit and the new state, so you can see exactly what it touched. Then practise the recovery: discard the change and return to your commit. Knowing you can do that is what makes bold prompting safe.',
      '[{"question":"What is a commit?","options":["A snapshot of the whole project at one moment, with a message, that you can return to","A backup copy of a single file","A request to publish your code online","A message sent to the AI"],"correct_index":0},{"question":"Why does version control matter more when an AI is writing the code?","options":["Large changes you did not write can be reverted cleanly when they go wrong","Git makes the AI produce better code","It is required before an AI can read your files","It prevents the AI from making mistakes"],"correct_index":0}]'::jsonb),
    (v_m2, 'Using Git and GitHub in Practice', 'A full beginner walkthrough of actually using Git and GitHub — installing, committing, pushing, and working with a repository. About 46 minutes, so work through it in sittings.', 'https://www.youtube.com/watch?v=tRZGeaHPoaw', 2,
      array['Initialise a repository and make your first commits', 'Push work to GitHub and understand what is now public', 'Use .gitignore to keep secrets and clutter out of the repository'],
      'This is the hands-on companion to the previous lesson. It runs about 46 minutes — a lot of data on a mobile bundle, so watch it in parts. The essential sequence is install, initialise, commit, push; the rest can wait until you need it.

Three things to hold onto as you follow along.

STAGING TRIPS UP EVERY BEGINNER. Git makes you choose what goes into a commit (`git add`) before making it (`git commit`). It feels like a pointless extra step until the day you want to commit two of four changed files, and then it is exactly right.

`.GITIGNORE` IS NOT OPTIONAL, and this is where the previous module connects. It lists files Git should never track. Your `.env` file — the one holding API keys — must be in it BEFORE your first push. Once a secret has been pushed to GitHub it is in the history even if you delete the file afterwards, and the only real fix is to revoke the key and issue a new one. Get this right the first time.

PUBLIC MEANS PUBLIC. A public GitHub repository is readable by anyone on earth, and automated bots scan new pushes for credentials continuously. If you are unsure, make it private — you can always open it later, but you cannot un-publish a key.

One genuine bonus for vibe coding: once your project is on GitHub, AI coding tools can read the whole repository for context, which measurably improves what they produce. Better answers, and a safety net, from the same habit.',
      'Put one real project on GitHub end to end: initialise the repository, create a `.gitignore` that excludes your environment file, make a commit with a meaningful message, and push. Then check the repository in your browser and confirm your `.env` is NOT there. Make it a private repository if there is any doubt.',
      '[{"question":"You accidentally pushed a file containing an API key to a public repository, then deleted the file and pushed again. Is the key safe?","options":["No — it remains in the history, and the key must be revoked and replaced","Yes, deleting the file removes it completely","Yes, as long as you deleted it within an hour","Only if the repository had no stars"],"correct_index":0},{"question":"What is the purpose of .gitignore?","options":["To list files Git should never track, such as the file holding your secrets","To hide files from your own editor","To compress the repository","To mark which files the AI may edit"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
